//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry, capped without overflowing on doubling.
    pub(crate) fn retry_delay_ms(&self, retry_number: u32) -> u64 {
        let delay = self
            .base_delay_ms
            .checked_mul(2u64.saturating_pow(retry_number.saturating_sub(1)))
            .unwrap_or(u64::MAX);
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_is_capped() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.retry_delay_ms(1), 10);
        assert_eq!(config.retry_delay_ms(2), 20);
        assert_eq!(config.retry_delay_ms(3), 25);
        assert_eq!(config.retry_delay_ms(4), 25);
    }
}

